/**
 * `X-E2E-Nonce` generation, reading and per-response verification.
 *
 * Contract (K-1 / K-2 / §8.1 D-1)
 * -------------------------------
 * * Header name: `X-E2E-Nonce`, compared case-insensitively (§7 K-1).
 * * Env var: `E2E_RUN_NONCE`, value = a UUID generated by `run_selfproof.py`.
 *   It lives **only** in process memory and in the spawned child's environment —
 *   never on disk, never inside any file of this repository.
 * * The header is emitted by **our own launcher wrapper**, so the ledger wording
 *   may only ever say 「该响应来自本 runner spawn 的那个进程」, never 「后端实现了
 *   nonce 协议」.
 *
 * Every response is asserted, not just the first one: a stream that carries the
 * nonce only on the handshake proves nothing about the responses behind it.
 * `NonceGuard` therefore counts checks and keeps a failure list shaped like the
 * `CaseOutcome.nonce_failures` field in the design (§3.1).
 *
 * Privacy: failures store a **fingerprint** of the observed value, never the
 * value itself, so evidence pasted into `.md` ledgers cannot leak the nonce.
 *
 * Exit codes: 32 (nonce absent / mismatched), 34 (nonce not configured).
 * This module performs no I/O of its own.
 */

import { createHash, randomUUID } from 'node:crypto';

import { NonceConfigError, NonceMismatchError } from './errors.mjs';

/** Header carrying the run nonce (§7 K-1). */
export const NONCE_HEADER = 'X-E2E-Nonce';

/** Lower-case form used for case-insensitive comparison. */
export const NONCE_HEADER_LOWER = NONCE_HEADER.toLowerCase();

/** Environment variable carrying the run nonce (§7 K-2). */
export const NONCE_ENV = 'E2E_RUN_NONCE';

/** Number of hex characters kept by `nonceFingerprint`. */
const FINGERPRINT_LENGTH = 12;

/**
 * Generate a fresh run nonce.
 *
 * @returns {string} A v4 UUID.
 */
export function generateNonce() {
  return randomUUID();
}

/**
 * Read the run nonce from the environment.
 *
 * @param {Record<string, string | undefined>} [env]
 * @returns {string} The trimmed nonce.
 * @throws {NonceConfigError} When `E2E_RUN_NONCE` is unset or blank (exit 34).
 */
export function resolveNonce(env = process.env) {
  const raw = env === null || env === undefined ? undefined : env[NONCE_ENV];
  const value = typeof raw === 'string' ? raw.trim() : '';
  if (value === '') {
    throw new NonceConfigError(
      `${NONCE_ENV} 未设置：nonce 只经子进程 env 传递，绝不落盘（K-2）。`
      + ' 请由 run_selfproof.py 生成并通过 env 注入。',
      { causeCode: 'NONCE_ENV_MISSING' },
    );
  }
  return value;
}

/**
 * Fingerprint a nonce so evidence can reference it without leaking it.
 *
 * @param {string|null|undefined} nonce
 * @returns {string} 12 hex chars, or `"absent"` / `"blank"`.
 */
export function nonceFingerprint(nonce) {
  if (nonce === null || nonce === undefined) {
    return 'absent';
  }
  const value = String(nonce).trim();
  if (value === '') {
    return 'blank';
  }
  return createHash('sha256').update(value, 'utf8').digest('hex').slice(0, FINGERPRINT_LENGTH);
}

/**
 * Read `X-E2E-Nonce` out of any header container.
 *
 * Accepts a WHATWG `Headers`, a `Map`, an array of `[name, value]` pairs, or a
 * plain object — comparison is always case-insensitive.
 *
 * @param {unknown} headers
 * @returns {string|null} The trimmed value, or `null` when absent/blank.
 */
export function readNonce(headers) {
  if (headers === null || headers === undefined) {
    return null;
  }

  if (typeof headers.get === 'function') {
    const direct = headers.get(NONCE_HEADER);
    const lowered = headers.get(NONCE_HEADER_LOWER);
    return firstNonBlank([direct, lowered]);
  }

  if (Array.isArray(headers)) {
    for (const entry of headers) {
      if (Array.isArray(entry) && entry.length >= 2
        && String(entry[0]).toLowerCase() === NONCE_HEADER_LOWER) {
        return firstNonBlank([entry[1]]);
      }
    }
    return null;
  }

  if (headers instanceof Map) {
    for (const [key, value] of headers.entries()) {
      if (String(key).toLowerCase() === NONCE_HEADER_LOWER) {
        return firstNonBlank([value]);
      }
    }
    return null;
  }

  if (typeof headers === 'object') {
    for (const [key, value] of Object.entries(headers)) {
      if (key.toLowerCase() === NONCE_HEADER_LOWER) {
        return firstNonBlank([value]);
      }
    }
  }
  return null;
}

/**
 * Return the first value that is a non-blank string.
 *
 * @param {unknown[]} candidates
 * @returns {string|null}
 */
function firstNonBlank(candidates) {
  for (const candidate of candidates) {
    if (typeof candidate === 'string' && candidate.trim() !== '') {
      return candidate.trim();
    }
  }
  return null;
}

/**
 * Collects one verdict per response and can prove "every response was checked".
 *
 * Unlike a bare `assert`, this keeps *all* failures, because the design's
 * `CaseOutcome` needs `nonce_failures` as a list (a single throw would hide the
 * pattern, e.g. "only the SSE stream lost the header").
 */
export class NonceGuard {
  #expected;
  #label;
  #checked = 0;
  #failures = [];
  #contexts = [];

  /**
   * @param {string} expected The run nonce (from `resolveNonce()`).
   * @param {{label?: string}} [options]
   */
  constructor(expected, options = {}) {
    const { label = 'e2e' } = options;
    if (typeof expected !== 'string' || expected.trim() === '') {
      throw new NonceConfigError('NonceGuard 需要非空 expected nonce', {
        causeCode: 'NONCE_EXPECTED_BLANK',
      });
    }
    this.#expected = expected.trim();
    this.#label = label;
  }

  /** @returns {string} Guard label, used in messages. */
  get label() {
    return this.#label;
  }

  /** @returns {number} How many responses have been checked. */
  get checked() {
    return this.#checked;
  }

  /** @returns {Array<{context: string, observed: string, reason: string}>} Copy of the failures. */
  get failures() {
    return this.#failures.map((failure) => ({ ...failure }));
  }

  /** @returns {boolean} True when no response failed the check. */
  get ok() {
    return this.#failures.length === 0;
  }

  /** @returns {string[]} The context labels of every checked response, in order. */
  get contexts() {
    return [...this.#contexts];
  }

  /**
   * Check one response and record the result (never throws).
   *
   * @param {unknown} headers
   * @param {string} [context] Human label, e.g. `"POST /api/v1/auth/register"`.
   * @returns {{ok: boolean, context: string, observed: string, reason: string}} Verdict
   *   where `observed` is a fingerprint, never the nonce itself.
   */
  check(headers, context) {
    this.#checked += 1;
    const label = typeof context === 'string' && context.trim() !== ''
      ? context.trim()
      : `response#${this.#checked}`;
    this.#contexts.push(label);

    const observed = readNonce(headers);
    let reason = 'ok';
    if (observed === null) {
      reason = 'absent';
    } else if (observed !== this.#expected) {
      reason = 'mismatch';
    }

    const verdict = {
      ok: reason === 'ok',
      context: label,
      observed: nonceFingerprint(observed),
      reason,
    };
    if (!verdict.ok) {
      this.#failures.push({
        context: label,
        observed: verdict.observed,
        reason: verdict.reason,
      });
    }
    return verdict;
  }

  /**
   * Check one response and throw immediately when it fails.
   *
   * @param {unknown} headers
   * @param {string} [context]
   * @returns {void}
   * @throws {NonceMismatchError} When the header is absent or mismatched (exit 32).
   */
  assert(headers, context) {
    const verdict = this.check(headers, context);
    if (verdict.ok) {
      return;
    }
    const what = verdict.reason === 'absent'
      ? `${NONCE_HEADER} 缺失`
      : `${NONCE_HEADER} 不符`;
    throw new NonceMismatchError(
      `${this.#label}: ${verdict.context} ${what}`
      + ` (observed=${verdict.observed} expected=${nonceFingerprint(this.#expected)})`,
      { causeCode: verdict.reason, details: verdict },
    );
  }

  /**
   * Throw when any recorded response failed.
   *
   * @returns {void}
   * @throws {NonceMismatchError} When at least one failure was recorded (exit 32).
   */
  assertClean() {
    if (this.ok) {
      return;
    }
    const first = this.#failures[0];
    throw new NonceMismatchError(
      `${this.#label}: ${this.#failures.length}/${this.#checked} 条响应 nonce 不合格`
      + `（首条 ${first.context} ${first.reason}）`,
      { causeCode: first.reason, details: { failures: this.failures, checked: this.#checked } },
    );
  }

  /**
   * Assert that at least `minimum` responses were checked.
   *
   * Guards against the vacuous case "we asserted every response, but there were
   * none" (K-11: an empty set is INVALID, never green).
   *
   * @param {number} minimum
   * @returns {void}
   * @throws {NonceMismatchError} When fewer responses than expected were checked.
   */
  assertCheckedAtLeast(minimum) {
    if (this.#checked >= minimum) {
      return;
    }
    throw new NonceMismatchError(
      `${this.#label}: 只校验了 ${this.#checked} 条响应，少于期望的 ${minimum} 条`
      + '（0 条校验 = 假绿）',
      { causeCode: 'TOO_FEW_RESPONSES', details: { checked: this.#checked, minimum } },
    );
  }

  /**
   * One-line summary for evidence (contains fingerprints only).
   *
   * @returns {string}
   */
  summary() {
    const failures = this.#failures.length;
    return `${this.#label}: nonce checks=${this.#checked} failures=${failures}`
      + ` expected=${nonceFingerprint(this.#expected)}`;
  }
}

/**
 * Shorthand: check a list of responses at once.
 *
 * @param {Array<{headers: unknown, context?: string}>} responses
 * @param {string} expected
 * @param {{label?: string, minimum?: number}} [options]
 * @returns {NonceGuard} The guard, already asserted clean.
 * @throws {NonceMismatchError} On the first failing response (exit 32).
 */
export function assertResponseNonces(responses, expected, options = {}) {
  const { label = 'e2e', minimum = 0 } = options;
  const guard = new NonceGuard(expected, { label });
  for (const response of responses) {
    guard.assert(response?.headers, response?.context);
  }
  guard.assertCheckedAtLeast(minimum);
  guard.assertClean();
  return guard;
}
